    image: 'assets/tiles/future-of-education.jpg',
    name: 'Alpha School',
    short: 'Alpha',
    tagline: 'Mastery · AI tutoring · 2-hour academics · limitless',
    era: 'USA · 2014–present',
    color: '#6D5AE0',
    colorDeep: '#4A38B0',
    colorSoft: '#ECE9FC',
    icon: 'rocket',
    built: true,
    blurb: "The boldest new model in this app — and, its founders would say, the future of school itself. Alpha School began when MacKenzie Price's own daughters told her school was boring, and has grown into a fast-spreading network of campuses — Austin, Miami, New York, San Francisco and more — built on one audacious promise: a child can crush the core academics in about two hours a day, and spend the rest of the day becoming a remarkable person. It works through AI-powered, one-to-one adaptive apps and a single hard rule — you only move on once you have truly mastered a thing — so children learn two to three times faster, routinely score in the top 1–2% nationally, and, above all, love going to school. The freed afternoons go to twenty-four real-world life skills and their own passions. This is that school, in its own words.",
    grab: {
      "summary": "Alpha School started with a simple complaint every parent knows. MacKenzie Price's own daughters told her that school was boring, and instead of shrugging, she asked a bigger question: what if a child could finish the core school subjects in about two hours a day, and spend the rest of the day becoming a remarkable person? That one idea has grown into a network of campuses across America, and the children there don't just learn faster. They love going.",
      "story": ["Alpha School began in Austin, Texas, in 2014. MacKenzie Price, a mum with a background in psychology, watched her two daughters lose their spark for learning. They told her school was boring. So she and her husband built something different, and it has since spread to campuses in Miami, New York, San Francisco and more.", "A day works in two parts. In the morning, each child sits with adaptive AI apps that act like a personal tutor, moving at exactly the right speed for that one child. The academic work is done in about two hours. The whole afternoon is then free for real-world life skills and each child's own passions and projects.", "What makes it distinctive is one simple rule: you only move on once you have truly mastered a thing. Not when the clock says so, and not when the class average is ready. Because the tutor is one-to-one, no child is bored waiting and no child is lost and left behind. The adults in the room are guides, not lecturers.", "This matters because it questions something we all just accept: that learning must fill six or seven hours a day. Alpha's first-principles answer is that most of that time is spent waiting, not learning. Give a child the right level and real mastery, and the reports say they learn two to three times faster and, more importantly, want to be there.", "One honest note. Alpha is young and bold, and its strongest claims come mostly from the school itself, not yet from long, independent study. It is still early days. So hold it as a genuinely exciting experiment worth watching, rather than a settled, proven answer, and let the results keep coming in over time."],
      hook: 'What Alpha is all about',
      deck: 'Seven simple ideas. Tap any one to open it.',
      bullets: [
        { t: 'Every child learns at their own pace', d: 'No one is dragged along or held back. Each child moves as fast or as slowly as they need, on work aimed at exactly them — never at the class average.' },
        { t: 'Traditional school wastes most of the day', d: 'A normal day is pitched at the middle of the class, so most kids spend it either bored or lost. Hours go to waiting, transitions and busywork.' },
        { t: 'The core academics only need about two hours', d: 'Reading, writing and maths — done properly, to real mastery — fit into two focused morning hours. And they’re done better than in a whole traditional day.' },
        { t: 'AI is the tutor, not the teacher', d: 'Adaptive apps meet each child one question at a time, right at their edge — the kind of personal tutoring that used to cost a fortune, now for every child at once.' },
        { t: 'The afternoon is for real life', d: 'With the core finished by lunch, the rest of the day goes to real skills and real passions — speaking, coding, building, enterprise, the outdoors, sport and art.' },
        { t: 'Guides replaced traditional teachers', d: 'Nobody lectures at a whiteboard. The adults are coaches who spark, unblock and cheer you on — while the child does the actual learning.' },
        { t: 'Success is mastering the learning, not sitting in class', d: 'You don’t move on when the calendar says so. You move on when you’ve genuinely mastered it — so no shaky gap comes back to sink you years later.' }
      ]
    },
